27: #define ENC_SUCCESS 1
28: #define ENC_FAILURE 0
29: #define DEC_SUCCESS 1
30: #define DEC_FAILURE 0
31: 
32: #define KEYGEN_ITERATION 1 << 19
33: #define KEYGEN_ITERATION2 1000
34: /* Should generate random salt for each repo. */
35: static unsigned char salt[8] = { 0xda, 0x90, 0x45, 0xc3, 0x06, 0xc7, 0xcc, 0x26 };
36: 
37: SeafileCrypt *
38: seafile_crypt_new (int version, unsigned char *key, unsigned char *iv)
39: {
40:     SeafileCrypt *crypt = g_new0 (SeafileCrypt, 1);
41:     crypt->version = version;
42:     if (version == 1)
43:         memcpy (crypt->key, key, 16);
44:     else
45:         memcpy (crypt->key, key, 32);
46:     memcpy (crypt->iv, iv, 16);
47:     return crypt;
48: }
49: 
50: int
51: seafile_derive_key (const char *data_in, int in_len, int version,
52:                     const char *repo_salt,
53:                     unsigned char *key, unsigned char *iv)
54: {
55: #ifdef USE_GPL_CRYPTO
56:     unsigned char repo_salt_bin[32];
57: 
58:     if (version == 4)
59:         hex_to_rawdata (repo_salt, repo_salt_bin, 32);
60: 
61:     switch (version) {
62:     case 1:
63:         seaf_warning ("Encrypted library version %d is not supported.\n", version);
64:         return -1;
65:     case 2:
66:         pbkdf2_hmac_sha256 (in_len, (const guchar *)data_in, KEYGEN_ITERATION2,
67:                             sizeof(salt), salt, 32, key);
68:         pbkdf2_hmac_sha256 (32, (const guchar *)key, 10, sizeof(salt), salt, 16, iv);
69:         break;
70:     case 3:
71:         seaf_warning ("Encrypted library version %d is not supported.\n", version);
72:         return -1;
73:     case 4:
74:         pbkdf2_hmac_sha256 (in_len, (const guchar *)data_in, KEYGEN_ITERATION2,
75:                             sizeof(repo_salt_bin), repo_salt_bin, 32, key);
76:         pbkdf2_hmac_sha256 (32, (const guchar *)key, 10, sizeof(repo_salt_bin), repo_salt_bin, 16, iv);
77:         break;
78:     default:
79:         seaf_warning ("Encrypted library version %d is not supported.\n", version);
80:         return -1;
81:     }
82: 
83:     return 0;
84: #else
85:     if (version >= 3) {
86:         unsigned char repo_salt_bin[32];
87: 
88:         hex_to_rawdata (repo_salt, repo_salt_bin, 32);
89: 
90:         PKCS5_PBKDF2_HMAC (data_in, in_len,
91:                            repo_salt_bin, sizeof(repo_salt_bin),
92:                            KEYGEN_ITERATION2,
93:                            EVP_sha256(),
94:                            32, key);
95:         PKCS5_PBKDF2_HMAC ((char *)key, 32,
96:                            repo_salt_bin, sizeof(repo_salt_bin),
97:                            10,
98:                            EVP_sha256(),
99:                            16, iv);
100:         return 0;
101:     } else if (version == 2) {
102:         PKCS5_PBKDF2_HMAC (data_in, in_len,
103:                            salt, sizeof(salt),
104:                            KEYGEN_ITERATION2,
105:                            EVP_sha256(),
106:                            32, key);
107:         PKCS5_PBKDF2_HMAC ((char *)key, 32,
108:                            salt, sizeof(salt),
109:                            10,
110:                            EVP_sha256(),
111:                            16, iv);
112:         return 0;
113:     } else if (version == 1) {
114:         EVP_BytesToKey (EVP_aes_128_cbc(), /* cipher mode */
115:                         EVP_sha1(),        /* message digest */
116:                         salt,              /* salt */
117:                         (unsigned char*)data_in,
118:                         in_len,
119:                         KEYGEN_ITERATION,   /* iteration times */
120:                         key, /* the derived key */
121:                         iv); /* IV, initial vector */
122:         return 0;
123:     } else {
124:         EVP_BytesToKey (EVP_aes_128_ecb(), /* cipher mode */
125:                         EVP_sha1(),        /* message digest */
126:                         NULL,              /* salt */
127:                         (unsigned char*)data_in,
128:                         in_len,
129:                         3,   /* iteration times */
130:                         key, /* the derived key */
131:                         iv); /* IV, initial vector */
132:         return 0;
133:     }
134: #endif
135: }
