137: int
138: seafile_generate_repo_salt (char *repo_salt)
139: {
140:     unsigned char repo_salt_bin[32];
141: 
142: #ifdef USE_GPL_CRYPTO
143:     int rc = gnutls_rnd (GNUTLS_RND_RANDOM, repo_salt_bin, sizeof(repo_salt_bin));
144:     if (rc != 0) {
145:         seaf_warning ("Failed to generate salt for repo encryption.\n");
146:         return -1;
147:     }
148: #else
149:     int rc = RAND_bytes (repo_salt_bin, sizeof(repo_salt_bin));
150:     if (rc != 1) {
151:         seaf_warning ("Failed to generate salt for repo encryption.\n");
152:         return -1;
153:     }
154: #endif
155: 
156:     rawdata_to_hex (repo_salt_bin, repo_salt, 32);
157: 
158:     return 0;
159: }
