161: int
162: seafile_generate_random_key (const char *passwd,
163:                              int version,
164:                              const char *repo_salt,
165:                              char *random_key)
166: {
167:     SeafileCrypt *crypt;
168:     unsigned char secret_key[32], *rand_key;
169:     int outlen;
170:     unsigned char key[32], iv[16];
171: 
172: #ifdef USE_GPL_CRYPTO
173:     if (gnutls_rnd (GNUTLS_RND_RANDOM, secret_key, sizeof(secret_key)) < 0) {
174:         seaf_warning ("Failed to generate secret key for repo encryption.\n");
175:         return -1;
176:     }
177: #else
178:     if (RAND_bytes (secret_key, sizeof(secret_key)) != 1) {
179:         seaf_warning ("Failed to generate secret key for repo encryption.\n");
180:         return -1;
181:     }
182: #endif
183: 
184:     seafile_derive_key (passwd, strlen(passwd), version, repo_salt, key, iv);
185: 
186:     crypt = seafile_crypt_new (version, key, iv);
187: 
188:     seafile_encrypt ((char **)&rand_key, &outlen,
189:                      (char *)secret_key, sizeof(secret_key), crypt);
190: 
191:     rawdata_to_hex (rand_key, random_key, 48);
192: 
193:     g_free (crypt);
194:     g_free (rand_key);
195: 
196:     return 0;
197: }
