199: void
200: seafile_generate_magic (int version, const char *repo_id,
201:                         const char *passwd,
202:                         const char *repo_salt,
203:                         char *magic)
204: {
205:     GString *buf = g_string_new (NULL);
206:     unsigned char key[32], iv[16];
207: 
208:     /* Compute a "magic" string from repo_id and passwd.
209:      * This is used to verify the password given by user before decrypting
210:      * data.
211:      */
212:     g_string_append_printf (buf, "%s%s", repo_id, passwd);
213: 
214:     seafile_derive_key (buf->str, buf->len, version, repo_salt, key, iv);
215: 
216:     g_string_free (buf, TRUE);
217:     rawdata_to_hex (key, magic, 32);
218: }
