221: seafile_generate_pwd_hash (int version,
222:                            const char *repo_id,
223:                            const char *passwd,
224:                            const char *repo_salt,
225:                            const char *algo,
226:                            const char *params_str,
227:                            char *pwd_hash)
228: {
