230:     unsigned char key[32];
231: 
232:     /* Compute a "pwd_hash" string from repo_id and passwd.
233:     * This is used to verify the password given by user before decrypting
234:     * data.
235:     */
236:     g_string_append_printf (buf, "%s%s", repo_id, passwd);
237: 
238:     if (version <= 2) {
