251: int
252: seafile_verify_repo_passwd (const char *repo_id,
253:                             const char *passwd,
254:                             const char *magic,
255:                             int version,
256:                             const char *repo_salt)
257: {
258:     GString *buf = g_string_new (NULL);
259:     unsigned char key[32], iv[16];
260:     char hex[65];
261: 
262:     if (version != 1 && version != 2 && version != 3 && version != 4) {
263:         seaf_warning ("Unsupported enc_version %d.\n", version);
264:         return -1;
265:     }
266: 
267:     /* Recompute the magic and compare it with the one comes with the repo. */
268:     g_string_append_printf (buf, "%s%s", repo_id, passwd);
269: 
270:     seafile_derive_key (buf->str, buf->len, version, repo_salt, key, iv);
271: 
272:     g_string_free (buf, TRUE);
273: 
274:     if (version >= 2)
275:         rawdata_to_hex (key, hex, 32);
276:     else
277:         rawdata_to_hex (key, hex, 16);
278: 
279:     if (g_strcmp0 (hex, magic) == 0)
280:         return 0;
281:     else
282:         return -1;
283: }
