318: int
319: seafile_decrypt_repo_enc_key (int enc_version,
320:                               const char *passwd, const char *random_key,
321:                               const char *repo_salt,
322:                               unsigned char *key_out, unsigned char *iv_out)
323: {
324:     unsigned char key[32], iv[16];
325: 
326:     seafile_derive_key (passwd, strlen(passwd), enc_version, repo_salt, key, iv);
327: 
328:     if (enc_version == 1) {
329:         memcpy (key_out, key, 16);
330:         memcpy (iv_out, iv, 16);
331:         return 0;
332:     } else if (enc_version >= 2) {
333:         unsigned char enc_random_key[48], *dec_random_key;
334:         int outlen;
335:         SeafileCrypt *crypt;
336: 
337:         if (random_key == NULL || random_key[0] == 0) {
338:             seaf_warning ("Empty random key.\n");
339:             return -1;
340:         }
341: 
342:         hex_to_rawdata (random_key, enc_random_key, 48);
343: 
344:         crypt = seafile_crypt_new (enc_version, key, iv);
345:         if (seafile_decrypt ((char **)&dec_random_key, &outlen,
346:                              (char *)enc_random_key, 48,
347:                              crypt) < 0) {
348:             seaf_warning ("Failed to decrypt random key.\n");
349:             g_free (crypt);
350:             return -1;
351:         }
352:         g_free (crypt);
353: 
354:         seafile_derive_key ((char *)dec_random_key, 32, enc_version,
355:                             repo_salt,
356:                             key, iv);
357:         memcpy (key_out, key, 32);
358:         memcpy (iv_out, iv, 16);
359: 
360:         g_free (dec_random_key);
361:         return 0;
362:     }
363: 
364:     return -1;
365: }
