367: int
368: seafile_update_random_key (const char *old_passwd, const char *old_random_key,
369:                            const char *new_passwd, char *new_random_key,
370:                            int enc_version, const char *repo_salt)
371: {
372:     unsigned char key[32], iv[16];
373:     unsigned char random_key_raw[48], *secret_key, *new_random_key_raw;
374:     int secret_key_len, random_key_len;
375:     SeafileCrypt *crypt;
376: 
377:     /* First, use old_passwd to decrypt secret key from old_random_key. */
378:     seafile_derive_key (old_passwd, strlen(old_passwd), enc_version,
379:                         repo_salt, key, iv);
380: 
381:     hex_to_rawdata (old_random_key, random_key_raw, 48);
382: 
383:     crypt = seafile_crypt_new (enc_version, key, iv);
384:     if (seafile_decrypt ((char **)&secret_key, &secret_key_len,
385:                          (char *)random_key_raw, 48,
386:                          crypt) < 0) {
387:         seaf_warning ("Failed to decrypt random key.\n");
388:         g_free (crypt);
389:         return -1;
390:     }
391:     g_free (crypt);
392: 
393:     /* Second, use new_passwd to encrypt secret key. */
394:     seafile_derive_key (new_passwd, strlen(new_passwd), enc_version,
395:                         repo_salt, key, iv);
396:     crypt = seafile_crypt_new (enc_version, key, iv);
397: 
398:     seafile_encrypt ((char **)&new_random_key_raw, &random_key_len,
399:                      (char *)secret_key, secret_key_len, crypt);
400: 
401:     rawdata_to_hex (new_random_key_raw, new_random_key, 48);
402: 
403:     g_free (secret_key);
404:     g_free (new_random_key_raw);
405:     g_free (crypt);
406: 
407:     return 0;
408: }
