412: int
413: seafile_encrypt (char **data_out,
414:                  int *out_len,
415:                  const char *data_in,
416:                  const int in_len,
417:                  SeafileCrypt *crypt)
418: {
419:     char *buf = NULL, *enc_buf = NULL;
420:     int buf_size, remain;
421:     guint8 padding;
422:     gnutls_cipher_hd_t handle;
423:     gnutls_datum_t key, iv;
424:     int rc, ret = 0;
425: 
426:     buf_size = BLK_SIZE * ((in_len / BLK_SIZE) + 1);
427:     remain = buf_size - in_len;
428:     buf = g_new (char, buf_size);
429: 
430:     memcpy (buf, data_in, in_len);
431:     padding = (guint8)remain;
432:     memset (buf + in_len, padding, remain);
433: 
434:     key.data = crypt->key;
435:     key.size = sizeof(crypt->key);
436:     iv.data = crypt->iv;
437:     iv.size = sizeof(crypt->iv);
438: 
439:     if (crypt->version == 1 || crypt->version == 3) {
440:         seaf_warning ("Encrypted library version % is not supported.\n", crypt->version);
441:         ret = -1;
442:         goto out;
443:     } else {
444:         rc = gnutls_cipher_init (&handle, GNUTLS_CIPHER_AES_256_CBC, &key, &iv);
445:         if (rc < 0) {
446:             seaf_warning ("Failed to init cipher: %s\n", gnutls_strerror(rc));
447:             ret = -1;
448:             goto out;
449:         }
450:     }
451: 
452:     enc_buf = g_new (char, buf_size);
453:     rc = gnutls_cipher_encrypt2 (handle, buf, buf_size, enc_buf, buf_size);
454:     if (rc < 0) {
455:         seaf_warning ("Failed to encrypt: %s\n", gnutls_strerror(rc));
456:         ret = -1;
457:         gnutls_cipher_deinit (handle);
458:         goto out;
459:     }
460: 
461:     gnutls_cipher_deinit (handle);
462: 
463: out:
464:     g_free (buf);
465:     if (ret < 0) {
466:         g_free (enc_buf);
467:         *data_out = NULL;
468:         *out_len = -1;
469:     } else {
470:         *data_out = enc_buf;
471:         *out_len = buf_size;
472:     }
473:     return ret;
474: }
475: 
476: int
477: seafile_decrypt (char **data_out,
478:                  int *out_len,
479:                  const char *data_in,
480:                  const int in_len,
481:                  SeafileCrypt *crypt)
482: {
483:     char *dec_buf = NULL;
484:     gnutls_cipher_hd_t handle;
485:     gnutls_datum_t key, iv;
486:     int rc, ret = 0;
487:     guint8 padding;
488:     int remain;
489: 
490:     if (in_len <= 0 || in_len % BLK_SIZE != 0) {
491:         seaf_warning ("Invalid encrypted buffer size.\n");
492:         return -1;
493:     }
494: 
495:     key.data = crypt->key;
496:     key.size = sizeof(crypt->key);
497:     iv.data = crypt->iv;
498:     iv.size = sizeof(crypt->iv);
499: 
500:     if (crypt->version == 1 || crypt->version == 3) {
501:         seaf_warning ("Encrypted library version %d is not supported.\n", crypt->version);
502:         ret = -1;
503:         goto out;
504:     } else {
505:         rc = gnutls_cipher_init (&handle, GNUTLS_CIPHER_AES_256_CBC, &key, &iv);
506:         if (rc < 0) {
507:             seaf_warning ("Failed to init cipher: %s\n", gnutls_strerror(rc));
508:             ret = -1;
509:             goto out;
510:         }
511:     }
512: 
513:     dec_buf = g_new (char, in_len);
514:     rc = gnutls_cipher_decrypt2 (handle, data_in, in_len, dec_buf, in_len);
515:     if (rc < 0) {
516:         seaf_warning ("Failed to decrypt data: %s\n", gnutls_strerror(rc));
517:         ret = -1;
518:         gnutls_cipher_deinit (handle);
519:         goto out;
520:     }
521: 
522:     padding = dec_buf[in_len - 1];
523:     remain = padding;
524:     *out_len = (in_len - remain);
525:     *data_out = dec_buf;
526: 
527:     gnutls_cipher_deinit (handle);
528: out:
529:     if (ret < 0) {
530:         g_free (dec_buf);
531:         *data_out = NULL;
532:         *out_len = -1;
533:     }
534:     return ret;
535: }
536: 
537: #else
538: 
539: int
540: seafile_encrypt (char **data_out,
541:                  int *out_len,
542:                  const char *data_in,
543:                  const int in_len,
544:                  SeafileCrypt *crypt)
545: {
546:     *data_out = NULL;
547:     *out_len = -1;
548: 
549:     /* check validation */
550:     if ( data_in == NULL || in_len <= 0 || crypt == NULL) {
551:         seaf_warning ("Invalid params.\n");
552:         return -1;
553:     }
554: 
555:     EVP_CIPHER_CTX *ctx;
556:     int ret;
557:     int blks;
558: 
559:     /* Prepare CTX for encryption. */
560:     ctx = EVP_CIPHER_CTX_new ();
561: 
562:     if (crypt->version == 1)
563:         ret = EVP_EncryptInit_ex (ctx,
564:                                   EVP_aes_128_cbc(), /* cipher mode */
565:                                   NULL, /* engine, NULL for default */
566:                                   crypt->key,  /* derived key */
567:                                   crypt->iv);  /* initial vector */
568:     else if (crypt->version == 3)
569:         ret = EVP_EncryptInit_ex (ctx,
570:                                   EVP_aes_128_ecb(), /* cipher mode */
571:                                   NULL, /* engine, NULL for default */
572:                                   crypt->key,  /* derived key */
573:                                   crypt->iv);  /* initial vector */
574:     else
575:         ret = EVP_EncryptInit_ex (ctx,
576:                                   EVP_aes_256_cbc(), /* cipher mode */
577:                                   NULL, /* engine, NULL for default */
578:                                   crypt->key,  /* derived key */
579:                                   crypt->iv);  /* initial vector */
580: 
581:     if (ret == ENC_FAILURE) {
582:         EVP_CIPHER_CTX_free (ctx);
583:         return -1;
584:     }
585: 
586:     /* Allocating output buffer. */
587:     
588:     /*
589:       For EVP symmetric encryption, padding is always used __even if__
590:       data size is a multiple of block size, in which case the padding
591:       length is the block size. so we have the following:
592:     */
593:     
594:     blks = (in_len / BLK_SIZE) + 1;
595: 
596:     *data_out = (char *)g_malloc (blks * BLK_SIZE);
597: 
598:     if (*data_out == NULL) {
599:         seaf_warning ("failed to allocate the output buffer.\n");
600:         goto enc_error;
601:     }                
602: 
603:     int update_len, final_len;
604: 
605:     /* Do the encryption. */
606:     ret = EVP_EncryptUpdate (ctx,
607:                              (unsigned char*)*data_out,
608:                              &update_len,
609:                              (unsigned char*)data_in,
610:                              in_len);
611: 
612:     if (ret == ENC_FAILURE)
613:         goto enc_error;
614: 
615: 
616:     /* Finish the possible partial block. */
617:     ret = EVP_EncryptFinal_ex (ctx,
618:                                (unsigned char*)*data_out + update_len,
619:                                &final_len);
620: 
621:     *out_len = update_len + final_len;
622: 
623:     /* out_len should be equal to the allocated buffer size. */
624:     if (ret == ENC_FAILURE || *out_len != (blks * BLK_SIZE))
625:         goto enc_error;
626:     
627:     EVP_CIPHER_CTX_free (ctx);
628: 
629:     return 0;
630: 
631: enc_error:
632: 
633:     EVP_CIPHER_CTX_free (ctx);
634: 
635:     *out_len = -1;
636: 
637:     if (*data_out != NULL)
638:         g_free (*data_out);
639: 
640:     *data_out = NULL;
641: 
642:     return -1;
643:     
644: }
645:                                
646: int
647: seafile_decrypt (char **data_out,
648:                  int *out_len,
649:                  const char *data_in,
650:                  const int in_len,
651:                  SeafileCrypt *crypt)
652: {
653:     *data_out = NULL;
654:     *out_len = -1;
655: 
656:     /* Check validation. Because padding is always used, in_len must
657:      * be a multiple of BLK_SIZE */
658:     if ( data_in == NULL || in_len <= 0 || in_len % BLK_SIZE != 0 ||
659:          crypt == NULL) {
660: 
661:         seaf_warning ("Invalid param(s).\n");
662:         return -1;
663:     }
664: 
665:     EVP_CIPHER_CTX *ctx;
666:     int ret;
667: 
668:     /* Prepare CTX for decryption. */
669:     ctx = EVP_CIPHER_CTX_new ();
670: 
671:     if (crypt->version == 1)
672:         ret = EVP_DecryptInit_ex (ctx,
673:                                   EVP_aes_128_cbc(), /* cipher mode */
674:                                   NULL, /* engine, NULL for default */
675:                                   crypt->key,  /* derived key */
