153:     char buf[10];
154:         
155:     memset (&hints, 0,sizeof (struct addrinfo));
156:     hints.ai_flags = AI_PASSIVE;
157:     hints.ai_family = AF_UNSPEC;
158:     hints.ai_socktype = SOCK_STREAM;
159: 
160:     snprintf (buf, sizeof(buf), "%d", port);
