162:     if ( (n = getaddrinfo(NULL, buf, &hints, &res) ) != 0) {
163:         ccnet_warning ("getaddrinfo fails: %s\n", gai_strerror(n));
164:         return -1;
165:     }
166: 
167:     ressave = res;
