172:         sockfd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
173:         if (sockfd < 0)
174:             continue;       /* error - try next one */
175: 
176: 		if (setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &on, sizeof(on)) < 0) {
177: 			ccnet_warning ("setsockopt of SO_REUSEADDR error\n");
